#!/bin/bash
# land-chat-delivered.sh — a message that arrives gets delivered. Fixes the
# single-tick bug end to end: rooms that survive a reconnect, server-side
# backlog delivery, presence sent to the right people, a Redis adapter that
# retries and says what its absence costs, full message history, and the
# "INCOMING UNDEFINED CALL" modal. Two new guard specs.
#
# BACKEND + FRONTEND. Push, and Railway + Vercel ship it.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="The words step off the picture"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-words-step-off.sh first."; exit 1 ;;
esac
NEEDS="A message that arrives gets delivered"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/land.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="7eadd433d3f85be38e8ecd9feaaa6b64b53b0df70a867cf63786e53724f9544c"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

echo "== API gates"
cd together-city-chat
npx tsc --noEmit
npx jest src/chat src/messages src/shared/unbounded-reads.spec.ts
cd ..

echo "== web gates"
cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS"
echo
echo " AFTER YOU PUSH, CHECK ONE THING ON RAILWAY:"
echo "   Is REDIS_URL set, and how many replicas run?"
echo " The adapter now says so loudly at boot either way — look for"
echo "   'Socket.IO Redis adapter connected'   (good), or"
echo "   'Redis adapter unavailable ... chat does NOT cross backend"
echo "    instances'                            (fix this if >1 replica)"
echo "==============================================================="
